from collections import deque
def comps(g,val):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    rr,cc=q.popleft(); comp.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==val and (nr,nc) not in seen:
                            seen.add((nr,nc)); q.append((nr,nc))
                out.append(comp)
    return out
