# Hypothesis: flood-fill from border over the BACKGROUND color; unreached bg cells -> holes -> flipped. Also holes may appear? Test.
def holes_flip(g,bg):
    H,W=len(g),len(g[0]); seen=set([(0,c) for c in range(W)]+[(r,0) for r in range(H)]+[(H-1,c) for c in range(W)]+[(r,W-1) for r in range(H)])
    q=deque(seen)
    while q:
        r,c=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and (rr,cc) not in seen and g[rr][cc]==bg:
                    seen.add((rr,cc)); q.append((rr,cc))
    fl={(r,c) for r in range(H) for c in range(W) if g[r][c]==bg and (r,c) not in seen}
    out=[row[:] for row in g]
    for r,c in fl:
        out[r][c]= (g[r][c]^1)  # placeholder colors handled later
    return out,set(fl)
